// Savings minimum balance withdrawal
public class Q05 {static class BankAccount {protected double balance=500; void deposit(double amount){if(amount>0)balance+=amount;} void withdraw(double amount){if(amount>0 && amount<=balance)balance-=amount;}} static class SavingsAccount extends BankAccount {@Override void withdraw(double amount){if(amount<=0 || balance-amount<100){System.out.println("Withdrawal rejected: minimum balance 100");return;}super.withdraw(amount);}} public static void main(String[] args){SavingsAccount a=new SavingsAccount();a.withdraw(450);a.withdraw(300);System.out.println("Balance: "+a.balance);}}
